class Gradebook:
    def __init__(self) -> None:
        # assignment_name -> {"weight": float, "kind": str}
        self.assignments: dict[str, dict] = {}
        # student_name -> {assignment_name: grade}
        self.grades: dict[str, dict[str, float]] = {}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = {"weight": float(weight), "kind": kind}

    def record(self, student: str, assignment: str, grade: float) -> None:
        if grade < 2.0 or grade > 5.0:
            raise ValueError(f"Grade {grade} is outside the allowed range of 2.0 to 5.0.")
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = float(grade)

    def average(self, student: str) -> float:
        student_grades = self.grades.get(student, {})
        if not student_grades:
            return 0.0

        # Collect quizzes taken by the student
        quizzes = [
            (name, student_grades[name])
            for name in student_grades
            if name in self.assignments and self.assignments[name]["kind"] == "quiz"
        ]

        # Determine if a quiz should be dropped (lowest quiz grade if more than one quiz taken)
        dropped_quiz_name = None
        if len(quizzes) > 1:
            # Drop lowest; tie-breaking drops any one lowest grade
            dropped_quiz_name = min(quizzes, key=lambda item: item[1])[0]

        total_weighted_sum = 0.0
        total_weight = 0.0

        for name, grade in student_grades.items():
            if name == dropped_quiz_name:
                continue
            if name in self.assignments:
                weight = self.assignments[name]["weight"]
                total_weighted_sum += grade * weight
                total_weight += weight

        if total_weight == 0.0:
            return 0.0

        return round(total_weighted_sum / total_weight, 2)
